'use strict';

function parseDuration(iso) {
  const m = iso.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!m) return null;
  const h = parseInt(m[1] || '0', 10);
  const min = parseInt(m[2] || '0', 10);
  const s = parseInt(m[3] || '0', 10);
  return (h * 3600 + min * 60 + s) * 1000;
}

// Remove entire (...)/[...] groups containing known video qualifier keywords
const BRACKET_SUFFIX_RE = /\s*[\[(][^\])\n]*(?:official|music\s*video|lyric|audio|remaster|visuali[sz]|live\s*ver|acoustic|hd|4k|explicit|radio\s*edit|single\s*ver|extended)[^\])\n]*[\])]/gi;
const BARE_SUFFIX_RE = /\s+(?:official|remastered?|hd|4k|live|explicit|audio)\s*$/gi;

/**
 * Extract clean { title, artist } from a raw YouTube video title + channel name.
 * Handles "Artist - Song Title (Official Music Video)" and auto-generated " - Topic" channels.
 */
function parseYouTubeTitle(rawTitle, channelTitle) {
  const channel = channelTitle.replace(/\s*-\s*Topic$/i, '').trim();

  let cleaned = rawTitle
    .replace(BRACKET_SUFFIX_RE, '')
    .replace(BARE_SUFFIX_RE, '')
    .trim();

  const sepIdx = cleaned.indexOf(' - ');
  if (sepIdx !== -1) {
    const left = cleaned.slice(0, sepIdx).trim();
    const right = cleaned.slice(sepIdx + 3).trim();
    const chanLower = channel.toLowerCase();
    if (left.toLowerCase() === chanLower || chanLower.includes(left.toLowerCase())) {
      return { title: right, artist: left };
    }
    if (right.toLowerCase() === chanLower || chanLower.includes(right.toLowerCase())) {
      return { title: left, artist: right };
    }
    return { title: right, artist: left };
  }

  return { title: cleaned, artist: channel };
}

function bestThumbnail(thumbnails) {
  const t = thumbnails || {};
  return (t.maxres || t.standard || t.high || t.medium || t.default)?.url || null;
}

module.exports = { parseDuration, parseYouTubeTitle, bestThumbnail };
