'use strict';

const FEAT_RE = /\s*[\(\[](feat\.?|ft\.?|featuring)[^\)\]]*[\)\]]/gi;
const REMASTER_RE = /\s*[\(\[](remastered?|re-?master[^\)\]]*|deluxe[^\)\]]*|anniversary[^\)\]]*|live[^\)\]]*|mono[^\)\]]*|stereo[^\)\]]*)[^\)\]]*[\)\]]/gi;
const PUNC_RE = /[^\w\s]/g;

function normalize(str) {
  if (!str) return '';
  return str
    .toLowerCase()
    .replace(FEAT_RE, '')
    .replace(REMASTER_RE, '')
    .replace(PUNC_RE, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenize(str) {
  return new Set(normalize(str).split(' ').filter(Boolean));
}

function jaccardSimilarity(a, b) {
  const setA = tokenize(a);
  const setB = tokenize(b);
  if (!setA.size && !setB.size) return 1;
  if (!setA.size || !setB.size) return 0;
  let intersection = 0;
  for (const token of setA) {
    if (setB.has(token)) intersection++;
  }
  const union = setA.size + setB.size - intersection;
  return intersection / union;
}

// Plan weights 0.15/0.10/0.05 sum to 0.30 — scaled up proportionally to 1.0
// so the 0.45 threshold is reachable: title:0.50 artist:0.35 duration:0.15
const WEIGHTS = { title: 0.50, artist: 0.35, duration: 0.15 };
const ACCEPT_THRESHOLD = 0.45;

/**
 * Score a search result against the source track metadata.
 * Returns null if below threshold.
 */
function findBestMatch(source, candidates) {
  // Short-circuit: adapter already gave us an ISRC match
  for (const c of candidates) {
    if (c.score === 1.0) return c;
  }

  // ISRC comparison (when both sides have it)
  if (source.isrc) {
    for (const c of candidates) {
      if (c.isrc && c.isrc === source.isrc) {
        return { ...c, score: 1.0 };
      }
    }
  }

  // Text + duration scoring
  let best = null;
  let bestScore = -Infinity;

  for (const c of candidates) {
    const titleSim = jaccardSimilarity(source.title, c.title);
    const artistSim = jaccardSimilarity(source.artist, c.artist);

    let durationSim = 0;
    if (source.durationMs && c.durationMs) {
      const diff = Math.abs(source.durationMs - c.durationMs);
      // Linear decay: 0 diff → 1.0, 10s diff → 0.0
      durationSim = Math.max(0, 1 - diff / 10000);
    }

    const score =
      WEIGHTS.title * titleSim +
      WEIGHTS.artist * artistSim +
      WEIGHTS.duration * durationSim;

    if (score > bestScore) {
      bestScore = score;
      best = { ...c, score: parseFloat(score.toFixed(4)) };
    }
  }

  if (best && bestScore >= ACCEPT_THRESHOLD) return best;
  return null;
}

module.exports = { findBestMatch };
