'use strict';

// Matches:
//   https://tidal.com/browse/track/123456789
//   https://listen.tidal.com/track/123456789
//   https://tidal.com/album/415141818/track/415141819
//   https://tidal.com/track/436551692/u
const RE = /(?:tidal\.com\/browse|listen\.tidal\.com)\/track\/(\d+)|tidal\.com\/album\/\d+\/track\/(\d+)|tidal\.com\/track\/(\d+)/;

function parse(url) {
  const m = url.match(RE);
  if (!m) return null;
  return { platform: 'tidal', trackId: m[1] || m[2] || m[3] };
}

module.exports = { parse };
