'use strict';

/**
 * @typedef {Object} TrackMeta
 * @property {string} title
 * @property {string} artist
 * @property {string} album
 * @property {string|null} isrc
 * @property {number|null} durationMs
 * @property {string|null} coverUrl
 * @property {string} url
 * @property {number} [score]
 */

/**
 * @typedef {Object} ResolveResult
 * @property {{ platform: string } & TrackMeta} source
 * @property {Record<string, (TrackMeta & { score: number }) | { error: string } | null>} results
 */

const { parseUrl } = require('./parsers');
const { findBestMatch } = require('./matcher');

const adapters = {
  spotify: require('./adapters/spotify'),
  appleMusic: require('./adapters/appleMusic'),
  youtubeMusic: require('./adapters/youtubeMusic'),
  deezer: require('./adapters/deezer'),
  tidal: require('./adapters/tidal'),
  youtube: require('./adapters/youtube'),
  yandexMusic: require('./adapters/yandexMusic'),
  soundcloud: require('./adapters/soundcloud'),
};

const ALL_PLATFORMS = Object.keys(adapters);

/**
 * Resolve a streaming service track URL to equivalent links on all other supported platforms.
 * @param {string} rawUrl - A track URL from any supported platform
 * @returns {Promise<ResolveResult>}
 */
async function resolve(rawUrl) {
  // 1. Parse URL
  const parsed = parseUrl(rawUrl);
  if (!parsed) {
    const err = new Error('Unrecognized or unsupported URL');
    err.status = 422;
    throw err;
  }

  const { platform, trackId } = parsed;
  const sourceAdapter = adapters[platform];

  // 2. Fetch source metadata
  let sourceMeta;
  try {
    sourceMeta = await sourceAdapter.getTrackMetadata(trackId);
  } catch (e) {
    const err = new Error(`Failed to fetch metadata from ${platform}: ${e.message}`);
    err.status = 502;
    throw err;
  }

  // 3. Fan out to all other platforms in parallel
  const targetPlatforms = ALL_PLATFORMS.filter(p => p !== platform);
  const query = { title: sourceMeta.title, artist: sourceMeta.artist, isrc: sourceMeta.isrc };

  const settledResults = await Promise.allSettled(
    targetPlatforms.map(p => adapters[p].searchTrack(query))
  );

  const results = { [platform]: { ...sourceMeta, score: 1.0 } };
  for (let i = 0; i < targetPlatforms.length; i++) {
    const p = targetPlatforms[i];
    const settled = settledResults[i];
    if (settled.status === 'rejected') {
      results[p] = { error: settled.reason?.message || 'search failed' };
    } else {
      const best = findBestMatch(sourceMeta, settled.value);
      results[p] = best || null;
    }
  }

  return {
    source: { platform, ...sourceMeta },
    results,
  };
}

module.exports = { resolve };
