'use strict';

// Matches:
//   https://music.apple.com/us/album/song-name/album-id?i=track-id
//   https://music.apple.com/us/song/song-name/track-id
const RE_QUERY = /music\.apple\.com\/[^/]+\/album\/[^?]+\?.*\bi=(\d+)/;
const RE_SONG = /music\.apple\.com\/[^/]+\/song\/[^/]+\/(\d+)/;

function parse(url) {
  let m = url.match(RE_QUERY);
  if (m) return { platform: 'appleMusic', trackId: m[1] };

  m = url.match(RE_SONG);
  if (m) return { platform: 'appleMusic', trackId: m[1] };

  return null;
}

module.exports = { parse };
