'use strict';

require('dotenv').config();

const required = ['SPOTIFY_CLIENT_ID', 'SPOTIFY_CLIENT_SECRET', 'YOUTUBE_API_KEY', 'TIDAL_CLIENT_ID', 'TIDAL_CLIENT_SECRET', 'SOUNDCLOUD_CLIENT_ID'];
const missing = required.filter(k => !process.env[k]);
if (missing.length) {
  console.warn(`Warning: missing env vars: ${missing.join(', ')} — related adapters will be unavailable`);
}

module.exports = {
  port: parseInt(process.env.PORT || '3000', 10),
  spotify: {
    clientId: process.env.SPOTIFY_CLIENT_ID || '',
    clientSecret: process.env.SPOTIFY_CLIENT_SECRET || '',
  },
  youtube: {
    apiKey: process.env.YOUTUBE_API_KEY || '',
  },
  tidal: {
    clientId: process.env.TIDAL_CLIENT_ID || '',
    clientSecret: process.env.TIDAL_CLIENT_SECRET || '',
    countryCode: process.env.TIDAL_COUNTRY || 'US',
  },
  soundcloud: {
    clientId: process.env.SOUNDCLOUD_CLIENT_ID || '',
  },
};
