'use strict';

const spotify = require('./spotify');
const appleMusic = require('./appleMusic');
const youtubeMusic = require('./youtubeMusic');
const deezer = require('./deezer');
const tidal = require('./tidal');
const youtube = require('./youtube');
const yandexMusic = require('./yandexMusic');
const soundcloud = require('./soundcloud');

// youtubeMusic must come before youtube so music.youtube.com is matched first
const parsers = [spotify, appleMusic, youtubeMusic, deezer, tidal, youtube, yandexMusic, soundcloud];

/**
 * Attempt to parse a raw URL into { platform, trackId }.
 * Returns null if no parser recognizes the URL.
 */
function parseUrl(rawUrl) {
  for (const parser of parsers) {
    const result = parser.parse(rawUrl);
    if (result) return result;
  }
  return null;
}

module.exports = { parseUrl };
