'use strict';

// Matches:
//   https://www.deezer.com/track/123456
//   https://www.deezer.com/en/track/123456
const RE = /deezer\.com(?:\/[a-z]{2}(?:-[a-zA-Z]+)*)?\/track\/(\d+)/;

function parse(url) {
  const m = url.match(RE);
  if (!m) return null;
  return { platform: 'deezer', trackId: m[1] };
}

module.exports = { parse };
