'use strict';

// Matches:
//   https://music.yandex.ru/album/123/track/456
//   https://music.yandex.com/album/123/track/456
const RE = /music\.yandex\.(?:ru|com)\/album\/(\d+)\/track\/(\d+)/;

function parse(url) {
  const m = url.match(RE);
  if (!m) return null;
  // Encode as "albumId:trackId" so the adapter can use the web handler fallback
  return { platform: 'yandexMusic', trackId: `${m[1]}:${m[2]}` };
}

module.exports = { parse };
