'use strict';

// Matches:
//   https://soundcloud.com/{user}/{slug}          — standard track URL
//   https://on.soundcloud.com/{shortcode}         — short link
// Excludes playlists: soundcloud.com/{user}/sets/...
const RE_TRACK = /^https?:\/\/soundcloud\.com\/([^/]+)\/(?!sets\/)([^/?#]+)/;
const RE_SHORT = /^https?:\/\/on\.soundcloud\.com\/[A-Za-z0-9]+/;

function parse(url) {
  if (RE_TRACK.test(url) || RE_SHORT.test(url)) {
    // Store the full URL — the /resolve endpoint accepts any SoundCloud URL
    return { platform: 'soundcloud', trackId: url.split('?')[0] };
  }
  return null;
}

module.exports = { parse };
